import React, { useState } from 'react';
import { ScrollTop } from 'primereact/scrolltop';

export default function Accessibility() {
    const [value, setValue] = useState('');
    
    return (
        <div>
            <label htmlFor="scrollTop-accessibility">Accessible ScrollTop</label>
            <ScrollTop 
                id="scrollTop-accessibility"
                value={value} 
                onChange={(e) => setValue(e.target.value)}
                aria-label="Accessible ScrollTop input"
                placeholder="Enter scrollTop"
            />
        </div>
    );
}